b={'JournalSHA256':hashlib.sha256(raw).hexdigest(),'JournalDevice':int(dev),'JournalInode':int(ino),'Namespace':run('readlink','/proc/1/ns/net').decode().strip(),'BootID':run('cat','/proc/sys/kernel/random/boot_id').decode().strip(),'NodeExecutableSHA256':exe,'NodeStartTicks':int(fields[19]),'OwnerID':payload['OwnerID'],'OrgID':entry['Engines'][0]['Binding']['OrgID'],'DeliveryID':entry['DeliveryID'],'CleanupID':entry['CleanupID'],'DesiredRevision':entry['CleanupDesiredRevision'],'GuardExpectedSHA256':hashlib.sha256(payload['Guards'][0]['ExpectedJSON'].encode()).hexdigest(),'CPDesiredIntent':provider['desired_intent'],'CPCleanupState':provider['cleanup_state'],'CPDesiredRevision':provider['desired_revision']}
