conf=run('cat','/run/tunnex-ipsec/strongswan.conf');cd,ci,cm,cu=run('stat','-c','%d %i %a %u','/run/tunnex-ipsec/strongswan.conf').decode().split();sd,si,sm,su=run('stat','-c','%d %i %a %u','/run/tunnex-ipsec/charon.vici').decode().split();assert cm==sm=='600'and cu==su=='0';b.update(CharonPID=pid,CharonStartTicks=int(cf[19]),CharonExecutableSHA256=ce,CharonConfigSHA256=hashlib.sha256(conf).hexdigest(),CharonConfigDevice=int(cd),CharonConfigInode=int(ci),SocketDevice=int(sd),SocketInode=int(si))
